// server/lib/organization-source.ts
function createOrganizationSource(token) {
  const octokit = new Octokit2({
    auth: token,
    baseUrl: process.env.GITHUB_API_URL || "https://api.github.com",
    request: { timeout: 3e4 }
  });
  return {
    async discover(config2) {
      try {
        const { data } = await octokit.orgs.get({ org: config2.organization });
        const organization = {
          login: data.login,
          name: data.name || null,
          description: data.description || null,
          avatarUrl: data.avatar_url || null,
          url: data.html_url
        };
        const repositories = await getOrganizationRepositories(octokit, organization, config2);
        return { organization, repositories };
      } catch {
        throw new Error(`Could not fetch all public repositories for ${config2.organization}`);
      }
    },
    async readme(owner, repo) {
      try {
        const { data } = await octokit.repos.getReadme({ owner, repo });
        return Buffer.from(data.content, "base64").toString("utf8");
      } catch (error63) {
        if (error63.status === 404) return "";
        throw new Error(`Could not fetch README for ${owner}/${repo}`);
      }
    },
    async structure(owner, repo) {
      try {
        const structure = await analyzeProjectStructure(token, owner, repo, {
          strict: true,
          octokit
        });
        structure.rootFiles.sort();
        structure.directories.sort();
        structure.packageFiles.sort((a, b) => a.name.localeCompare(b.name));
        structure.configFiles.sort((a, b) => a.name.localeCompare(b.name));
        structure.sourceFiles.sort((a, b) => a.name.localeCompare(b.name));
        structure.techStack.sort();
        return generateProjectSummary(structure);
      } catch (error63) {
        if (error63.status === 404) return "No project files available.";
        throw new Error(`Could not analyze project structure for ${owner}/${repo}`);
      }
    }
  };
}

